//! Generated from pinned Unicode 16.0.0 UCD files. Do not edit.
//! Run src/tools/generate-normalization-properties.py to regenerate.
//!
//! Canonical (NFC/NFD) and compatibility (NFKC/NFKD) normalization.
//! Canonical and compatibility decompositions live in separate tables:
//! canonical mappings are at most two scalars immediate and pack a
//! one-bit pair flag; compatibility mappings run up to 18 scalars
//! immediate and instead derive each entry's length from the next
//! entry's offset. See the generator module docstring for why.
//!
//! Only a few thousand of the 1,114,112 code points carry any of these
//! facts, so these are sorted arrays searched by bisection rather than
//! the two-stage trie properties.zig uses: at this density the trie's
//! index alone costs more than this entire layout. Hangul is algorithmic
//! and appears in no table, for either form.

pub const QuickCheck = enum(u2) { yes, no, maybe };

/// Every per-character fact that is not a mapping, in one value.
///
/// `composition_base` and `composable` are the two halves of the
/// composition question: a pair can only compose when the first is a
/// base and the second is composable. Most of Unicode is neither, which
/// is what keeps the composition table out of the common path. NFKC
/// composes with the same two fields as NFC -- compatibility mappings
/// are never recomposed, so this question does not change per form.
pub const Class = packed struct(u16) {
    ccc: u8,
    quick_check: QuickCheck,
    decomposes: bool,
    composition_base: bool,
    composable: bool,
    nfkc_quick_check: QuickCheck,
    compat_decomposes: bool,
};

